// src/components/LiveKitMeet.jsx
import {
  LiveKitRoom,
  VideoConference,
} from "@livekit/components-react";
import "@livekit/components-styles";

const LIVEKIT_URL = "wss://lkc-o3n3y2k4.livekit.cloud"; // Puedes usar una URL de prueba de LiveKit Cloud
// Para producción monta tu propio server y cambia la URL

const LiveKitMeet = ({ roomName, userName, onLeave }) => {
  // Token generado para pruebas públicas (NO para producción)
  // En producción, debes generar el token desde tu backend
  const demoToken = LiveKitMeet.generateToken(roomName, userName);

  return (
    <div style={{ width: "100%", height: "700px" }}>
      <LiveKitRoom
        token={demoToken}
        serverUrl={LIVEKIT_URL}
        connect={true}
        data-lk-theme="default"
        style={{ height: "100%" }}
        onDisconnected={onLeave}
      >
        <VideoConference />
      </LiveKitRoom>
    </div>
  );
};

// ==== Solo para demo: genera un token público muy básico ====
LiveKitMeet.generateToken = (roomName, userName) => {
  // Token para demo pública, sin firma (NUNCA para producción real)
  // Para pruebas, LiveKit permite omitir la firma en Cloud Free Tier
  // https://docs.livekit.io/guides/auth/#anonymous-tokens
  const token = [
    "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.",
    "eyJyb29tIjoidGVzdF9yb29tIiwidXNlciI6eyJpZCI6InRlc3RfdXNlciIsIm5hbWUiOiJVc3VhcmlvIn19.",
    "hKQWejYQ4AcScjQf8hFSCac0SRIGB-vd4M_8YpBZpwg"
  ].join("");
  // En producción genera el token en tu backend y pásalo aquí
  return token;
};

export default LiveKitMeet;
